"""Interface definitions."""

import abc
import asyncio
import collections.abc
import os
import typing

from jsilib import _utils
from jsilib.base import IClosable

__all__ = export = _utils.ExportList(['EventListener'])

T = typing.TypeVar('T')

EventListener = typing.Union[typing.Callable[['Event'], None], typing.Callable[['Event'], typing.Coroutine]]


@export
class ITask(abc.ABC, collections.abc.Awaitable):
    """Provides interface for asynchronous background tasks."""

    @abc.abstractmethod
    def name(self) -> str:
        """Return the name of this task."""

    @abc.abstractmethod
    def done(self) -> bool:
        """Check if this task is done."""

    @abc.abstractmethod
    def cancel_nowait(self):
        """Schedule cancellation of this task."""

    @abc.abstractmethod
    async def cancel(self):
        """Schedule cancellation of this task and await for cancellation to complete."""

    @abc.abstractmethod
    def result(self) -> typing.Any:
        """Return task's result."""


@export
class Event(abc.ABC):
    """Base class for events."""


@export
class IReactor(IClosable):

    @property
    @abc.abstractmethod
    def event_loop(self) -> asyncio.AbstractEventLoop:
        """Reference to the event loop this reactor is using internally."""

    @abc.abstractmethod
    def call_soon(self, func: typing.Callable, *args, **kwargs) -> int:
        """Schedule *func* to be executed as soon as possible.

        Return task ID that can later be used with a :meth:`cancel` to prevent
        scheduled *func* from executing.

        :param func:
            Function to be scheduled.

        :param `*args`:
            Optional positional args the function will be executed with.

        :param `**kwargs`:
            Optional named args the function will be executed with.
        """

    @abc.abstractmethod
    def call_later(self, delay: float, func: typing.Callable, *args, **kwargs) -> int:
        """Schedule *func* to be called not earlier than after *delay*
        seconds.

        Return task ID that can later be used with a :meth:`cancel` to prevent
        scheduled *func* from executing.

        :param delay:
            Delay time (in seconds)

        :param func:
            Function to be called

        :param `*args`:
            Positional arguments to be bound with *func* (optional)

        :param `**kwargs`:
            Keyword arguments to be bound with *func* (optional)
        """

    @abc.abstractmethod
    def cancel(self, task_id: int) -> bool:
        """Cancel tasks created by :meth:`call_later` or :meth:`call_soon`.

        Returns ``True`` if task was cancelled or ``False`` if *task_id* was
        already cancelled, finished or invalid.

        :param task_id:
            Task ID returned by :meth:`call_later` or :meth:`call_soon`.
        """

    @abc.abstractmethod
    def notify(self, event: Event):
        """Schedule event notification.

        After this method is called, all subscribers that are subscribed for
        events of given type will be called soon and *event* will be passed as
        an argument.

        :param event:
            Event object to trigger listeners with
        """

    @abc.abstractmethod
    def subscribe(self, listener: EventListener, event_type: typing.Type[Event]) -> int:
        """Subscribe for events of given type.

        Returns ID assigned to this listener.

        :param listener:
            Listener to be subscribed

        :param event_type:
            Type of event to subscribe to.

            This should be a subclass of :class:`IEvent`.
        """

    @abc.abstractmethod
    def unsubscribe(self, listener_id: int) -> bool:
        """Removes listener matching given ID from the list of listeners.

        As an effect, corresponding listener will not get called again.

        :param listener_id:
            The ID of listener returned by :meth:`subscribe`
        """

    @abc.abstractmethod
    async def run_blocking(self, func: typing.Callable[[], T], *args, **kwargs) -> T:
        """Run given non-async *func* in a background thread and await for it
        to complete.

        This method is used to execute blocking function just like it was a
        normal coroutine.

        :param func:
            The non-async function to be scheduled for execution.

        :param `*args`:
            Positional args to be bound to *func*.

        :param `**kwargs`:
            Named args to be bound to *func*.
        """

    @abc.abstractmethod
    def run(self, coroutine: typing.Coroutine) -> ITask:
        """Run given *coroutine* as a background task.

        Returned :class:`ITask` object can be later used to interact with
        created task by either waiting for it to finish or cancelling it.

        All tasks that were not yet executed will be cancelled during reactor's
        shutdown.

        :param coroutine:
            Coroutine to be scheduled as a task.
        """


@export
class IStreamReader(abc.ABC):
    """Base class for readable streams."""

    @abc.abstractmethod
    async def read(self, count: int) -> bytes:
        pass


@export
class IStreamWriter(abc.ABC):
    """Base class for writable streams."""

    @abc.abstractmethod
    async def write(self, data: bytes) -> int:
        pass


@export
class IReadOnlyStream(IStreamReader, IClosable):
    """Base class for read-only closable streams."""


@export
class IWriteOnlyStream(IStreamWriter, IClosable):
    """Base class for write-only closable streams."""


@export
class IStream(IStreamReader, IStreamWriter, IClosable):
    """Base class for read/write closable streams."""


@export
class IAcceptor(IClosable):
    """Interface for server-side stream factories."""

    @abc.abstractmethod
    async def accept(self) -> IStream:
        """Accept incoming connection and return as a new :class:`IStream`
        object.

        Returned object can later be used to exchange data with remote peer.
        """


@export
class ITemporaryDirectory(IClosable, os.PathLike):
    """Interface to a temporary directory.

    Given temporary directory should be bound with a given instance of this
    class (1-1) and removed once the instance is closed.
    """

    @property
    @abc.abstractmethod
    def path(self) -> str:
        pass
